export type BlogChecklistItem = {
  id: string;
  label: string;
};

export type BlogQuizQuestion = {
  id: string;
  question: string;
  options: string[];
  /** index in options */
  correct: number;
  explain: string;
};

export type BlogQuizBlock = {
  title: string;
  lead: string;
  questions: BlogQuizQuestion[];
  /** Insert after section whose title includes this */
  afterTitleIncludes: string;
};

export type BlogInteractConfig = {
  checklist: {
    title: string;
    lead: string;
    items: BlogChecklistItem[];
    afterTitleIncludes: string;
  };
  quizzes: BlogQuizBlock[];
};

